cat > src/deadnix.py <<'PY'
#!/usr/bin/env python3
import sys, os, json, re
from dataclasses import dataclass, field

VERSION = "deadnix 1.3.1"

IDENT_RE = re.compile(r"[A-Za-z_][A-Za-z0-9_'-]*")
KEYWORDS = {"let","in","inherit","rec","with","assert","if","then","else","or"}

@dataclass
class Tok:
    typ: str
    val: str
    start: int
    end: int
    line: int
    col: int
    end_line: int
    end_col: int

@dataclass
class Ref:
    name: str
    tok: Tok
    scope: object

@dataclass
class Expr:
    refs: list = field(default_factory=list)
    children: list = field(default_factory=list)
    lets: list = field(default_factory=list)

@dataclass
class Scope:
    parent: object = None
    decls: list = field(default_factory=list)
    byname: dict = field(default_factory=dict)
    body: Expr = None
    kind: str = "scope"

@dataclass
class Decl:
    name: str
    tok: Tok
    kind: str
    scope: Scope
    expr: Expr = None
    reportable: bool = True
    pattern_field: bool = False
    used: bool = False
    warned_used: bool = False
    remove_span: tuple = None
    rename_pos: int = None

@dataclass
class ParseResult:
    root: Expr
    root_scope: Scope
    errors: list = field(default_factory=list)
    decls: list = field(default_factory=list)

class Lexer:
    def __init__(self, text):
        self.text=text
        self.n=len(text)
        self.line_starts=[0]
        for m in re.finditer('\n', text):
            self.line_starts.append(m.end())
        self.skip_lines=set()

    def posline(self,pos):
        # binary search
        import bisect
        i=bisect.bisect_right(self.line_starts,pos)-1
        return i+1, pos-self.line_starts[i]+1

    def make(self, typ, val, s, e):
        l,c=self.posline(s); el,ec=self.posline(e)
        return Tok(typ,val,s,e,l,c,el,ec)

    def matching_brace(self, i):
        depth=1; j=i
        while j<self.n:
            ch=self.text[j]
            if ch=='"':
                j=self.skip_dquote(j); continue
            if self.text.startswith("''", j):
                j=self.skip_indented(j); continue
            if self.text.startswith('/*', j):
                k=self.text.find('*/', j+2); j=self.n if k<0 else k+2; continue
            if ch=='#':
                k=self.text.find('\n', j); j=self.n if k<0 else k+1; continue
            if ch=='{': depth+=1
            elif ch=='}':
                depth-=1
                if depth==0: return j
            j+=1
        return self.n

    def skip_dquote(self, i):
        j=i+1
        while j<self.n:
            if self.text.startswith('${', j):
                k=self.matching_brace(j+2)
                j = k+1 if k<self.n else self.n
                continue
            if self.text[j]=='\\': j+=2; continue
            if self.text[j]=='"': return j+1
            j+=1
        return self.n

    def skip_indented(self, i):
        j=i+2
        while j<self.n:
            if self.text.startswith("''${", j):
                k=self.matching_brace(j+4)
                j = k+1 if k<self.n else self.n
                continue
            if self.text.startswith("''", j): return j+2
            j+=1
        return self.n

    def lex_range(self, start=0, end=None):
        if end is None: end=self.n
        toks=[]; i=start; text=self.text
        while i<end:
            ch=text[i]
            if ch.isspace(): i+=1; continue
            if ch=='#':
                j=text.find('\n', i, end)
                if j<0: j=end
                comment=text[i:j]
                if 'deadnix: skip' in comment:
                    line,_=self.posline(i); self.skip_lines.add(line+1)
                i=j; continue
            if text.startswith('/*', i):
                j=text.find('*/', i+2, end); i=end if j<0 else j+2; continue
            if ch=='"':
                # emit tokens inside ${...}, not string contents
                j=i+1
                while j<end:
                    if text.startswith('${', j):
                        k=self.matching_brace(j+2)
                        toks.extend(self.lex_range(j+2, min(k,end)))
                        j = k+1 if k<end else end
                        continue
                    if text[j]=='\\': j+=2; continue
                    if text[j]=='"': j+=1; break
                    j+=1
                i=j; continue
            if text.startswith("''", i):
                j=i+2
                while j<end:
                    if text.startswith("''${", j):
                        k=self.matching_brace(j+4)
                        toks.extend(self.lex_range(j+4, min(k,end)))
                        j = k+1 if k<end else end
                        continue
                    if text.startswith("''", j): j+=2; break
                    j+=1
                i=j; continue
            m=IDENT_RE.match(text,i)
            if m:
                val=m.group(0); typ='KW' if val in KEYWORDS else 'IDENT'
                toks.append(self.make(typ,val,i,m.end())); i=m.end(); continue
            if text.startswith('...', i):
                toks.append(self.make('ELLIPSIS','...',i,i+3)); i+=3; continue
            if text.startswith('==', i) or text.startswith('!=', i) or text.startswith('<=', i) or text.startswith('>=', i) or text.startswith('&&', i) or text.startswith('||', i) or text.startswith('->', i) or text.startswith('//', i):
                toks.append(self.make('OP',text[i:i+2],i,i+2)); i+=2; continue
            if ch in '{}()[];:=,?@.':
                toks.append(self.make(ch,ch,i,i+1)); i+=1; continue
            # paths, numbers, operators etc.
            toks.append(self.make('OP',ch,i,i+1)); i+=1
        return toks

def is_ident(t): return t is not None and t.typ=='IDENT'
def is_kw(t,v): return t is not None and t.typ=='KW' and t.val==v

class Parser:
    def __init__(self, text):
        self.text=text
        self.lex=Lexer(text)
        self.toks=self.lex.lex_range()
        self.i=0
        self.errors=[]
        self.all_decls=[]

    def peek(self, off=0):
        j=self.i+off
        return self.toks[j] if 0<=j<len(self.toks) else None
    def pop(self):
        t=self.peek(); self.i+=1; return t
    def at_stop(self, stops):
        t=self.peek()
        if t is None: return 'EOF' in stops
        return t.val in stops or t.typ in stops or (t.typ=='KW' and t.val in stops)
    def add_decl(self, scope, name, tok, kind, expr=None, reportable=True, pattern_field=False):
        d=Decl(name,tok,kind,scope,expr,reportable,pattern_field)
        scope.decls.append(d); scope.byname.setdefault(name,[]).append(d); self.all_decls.append(d); return d

    def parse(self):
        root_scope=Scope(None, kind='root')
        if not self.toks:
            self.errors.append({'message':'unexpected end of file'})
            return ParseResult(Expr(), root_scope, self.errors, self.all_decls)
        root=self.parse_expr(root_scope, {'EOF'})
        root_scope.body=root
        return ParseResult(root, root_scope, self.errors, self.all_decls)

    def parse_expr(self, scope, stops):
        e=Expr()
        while self.peek() is not None and not self.at_stop(stops):
            t=self.peek()
            if is_kw(t,'let'):
                child=self.parse_let(scope); e.children.append(child); e.lets.append(child); continue
            if self.is_lambda_start():
                child=self.parse_lambda(scope); e.children.append(child); continue
            if is_kw(t,'rec') and self.peek(1) and self.peek(1).val=='{':
                self.pop(); child=self.parse_attrset(scope, rec=True); e.children.append(child); continue
            if t.val=='{':
                child=self.parse_attrset(scope, rec=False); e.children.append(child); continue
            if t.val=='(':
                self.pop(); child=self.parse_expr(scope, {')','EOF'}); e.children.append(child)
                if self.peek() and self.peek().val==')': self.pop()
                continue
            if t.val=='[':
                self.pop(); child=self.parse_expr(scope, {']','EOF'}); e.children.append(child)
                if self.peek() and self.peek().val==']': self.pop()
                continue
            if is_ident(t):
                # Ignore selector component after dot and the attribute name in `? name` hasAttr.
                prev=self.toks[self.i-1] if self.i>0 else None
                nxt=self.peek(1)
                if not (prev and prev.val=='.'):
                    # If this is an attrpath segment before '=' in a context we failed to parse, it may be a false ref;
                    # common attrsets are handled by parse_attrset.
                    e.refs.append(Ref(t.val,t,scope))
                self.pop(); continue
            self.pop()
        return e

    def is_lambda_start(self):
        t=self.peek()
        if is_ident(t) and self.peek(1) and self.peek(1).val==':': return True
        if is_ident(t) and self.peek(1) and self.peek(1).val=='@' and self.peek(2) and self.peek(2).val=='{':
            end=self.find_matching(self.i+2,'{','}')
            return end is not None and self.toks[end+1:end+2] and self.toks[end+1].val==':'
        if t and t.val=='{':
            end=self.find_matching(self.i,'{','}')
            if end is None: return False
            nt=self.toks[end+1] if end+1<len(self.toks) else None
            if nt and nt.val==':':
                return self.looks_like_pattern(self.i+1,end)
            if nt and nt.val=='@' and end+2<len(self.toks) and is_ident(self.toks[end+2]) and end+3<len(self.toks) and self.toks[end+3].val==':':
                return self.looks_like_pattern(self.i+1,end)
        return False

    def looks_like_pattern(self, a, b):
        # Pattern entries are identifiers with comma/defaults/ellipsis, not attr assignments.
        depth=0
        has_ident=False
        for k in range(a,b):
            tok=self.toks[k]
            if tok.val in '([{': depth+=1
            elif tok.val in ')]}': depth-=1
            elif depth==0 and tok.val=='=':
                return False
            elif depth==0 and (tok.typ=='IDENT' or tok.typ=='ELLIPSIS'):
                has_ident=True
        return True

    def find_matching(self, idx, openv, closev):
        depth=0
        for k in range(idx,len(self.toks)):
            if self.toks[k].val==openv: depth+=1
            elif self.toks[k].val==closev:
                depth-=1
                if depth==0: return k
        return None

    def parse_lambda(self, parent_scope):
        lam_scope=Scope(parent_scope, kind='lambda')
        e=Expr(); e.children.append(Expr())
        t=self.peek()
        if is_ident(t) and self.peek(1) and self.peek(1).val==':':
            self.pop(); self.pop()
            reportable=not t.val.startswith('_')
            self.add_decl(lam_scope,t.val,t,'lambda_arg',None,reportable,False).rename_pos=t.start
            body=self.parse_expr(lam_scope, {'EOF',';',')',']','}',','})
            lam_scope.body=body; e.children=[body]
            return e
        alias_tok=None
        if is_ident(t) and self.peek(1) and self.peek(1).val=='@':
            alias_tok=self.pop(); self.pop() # @
            self.parse_pattern_body(lam_scope)
            if self.peek() and self.peek().val==':': self.pop()
        elif t and t.val=='{':
            self.parse_pattern_body(lam_scope)
            if self.peek() and self.peek().val=='@':
                self.pop()
                if is_ident(self.peek()): alias_tok=self.pop()
            if self.peek() and self.peek().val==':': self.pop()
        if alias_tok:
            d=self.add_decl(lam_scope,alias_tok.val,alias_tok,'lambda_pattern',None,True,False); d.rename_pos=alias_tok.start
        body=self.parse_expr(lam_scope, {'EOF',';',')',']','}',','})
        lam_scope.body=body; e.children=[body]
        return e

    def parse_pattern_body(self, scope):
        if not (self.peek() and self.peek().val=='{'): return
        self.pop()
        while self.peek() is not None and self.peek().val!='}':
            if self.peek().typ=='ELLIPSIS': self.pop()
            elif is_ident(self.peek()):
                name_tok=self.pop()
                default_expr=None
                if self.peek() and self.peek().val=='?':
                    self.pop()
                    default_expr=self.parse_expr(scope, {',','}','EOF'})
                d=self.add_decl(scope,name_tok.val,name_tok,'lambda_pattern',default_expr,True,True); d.rename_pos=name_tok.start
            else:
                self.pop()
            if self.peek() and self.peek().val==',': self.pop()
        if self.peek() and self.peek().val=='}': self.pop()

    def parse_let(self, parent_scope):
        let_tok=self.pop()
        let_scope=Scope(parent_scope, kind='let')
        e=Expr()
        # First pass parse declarations and their value expressions in the let scope.
        while self.peek() is not None and not is_kw(self.peek(),'in'):
            if is_kw(self.peek(),'inherit'):
                self.parse_let_inherit(let_scope)
                continue
            if is_ident(self.peek()):
                name_tok=self.pop()
                # skip attrpath segments until '='; dynamic pieces are parsed as part of attr path and count as deps
                path_refs=[]
                while self.peek() is not None and self.peek().val not in {'=',';'} and not is_kw(self.peek(),'in'):
                    if self.peek().val=='(':
                        self.pop(); path_refs.append(self.parse_expr(let_scope,{')','EOF'}))
                        if self.peek() and self.peek().val==')': self.pop()
                    else:
                        self.pop()
                if self.peek() and self.peek().val=='=':
                    self.pop()
                    valexpr=self.parse_expr(let_scope, {';','EOF'})
                    for pr in path_refs: valexpr.children.append(pr)
                    reportable = name_tok.line not in self.lex.skip_lines
                    d=self.add_decl(let_scope,name_tok.val,name_tok,'let',valexpr,reportable,False)
                    d.remove_span=self.binding_remove_span(name_tok.start)
                if self.peek() and self.peek().val==';': self.pop()
                continue
            # skip unexpected tokens
            self.pop()
        if self.peek() and is_kw(self.peek(),'in'):
            self.pop()
            body=self.parse_expr(let_scope, {'EOF',';',')',']','}',','})
        else:
            body=Expr(); self.errors.append({'message':'unexpected end of file'})
        let_scope.body=body
        e.children.append(body); e.lets.append(let_scope)
        return e

    def parse_let_inherit(self, scope):
        inh_tok=self.pop()
        source_expr=None
        if self.peek() and self.peek().val=='(':
            self.pop(); source_expr=self.parse_expr(scope,{')','EOF'})
            if self.peek() and self.peek().val==')': self.pop()
        while self.peek() is not None and self.peek().val!=';' and not is_kw(self.peek(),'in'):
            if is_ident(self.peek()):
                nt=self.pop()
                expr=source_expr if source_expr is not None else Expr(refs=[Ref(nt.val,nt,scope.parent or scope)])
                reportable=nt.line not in self.lex.skip_lines
                d=self.add_decl(scope,nt.val,nt,'let',expr,reportable,False)
                d.remove_span=self.binding_remove_span(inh_tok.start)
            else:
                self.pop()
        if self.peek() and self.peek().val==';': self.pop()

    def parse_attrset(self, parent_scope, rec=False):
        # consume opening brace
        if self.peek() and self.peek().val=='{': self.pop()
        scope=parent_scope
        attr_scope=None
        e=Expr()
        if rec:
            attr_scope=Scope(parent_scope, kind='recattr')
            scope=attr_scope
        # In a rec attrset, collect simple attr names in advance to shadow outer vars.
        if rec:
            save=self.i; depth=0
            while self.peek() is not None:
                if self.peek().val=='{': depth+=1
                elif self.peek().val=='}':
                    if depth==0: break
                    depth-=1
                if depth==0 and is_ident(self.peek()) and self.peek(1) and self.peek(1).val=='=':
                    tok=self.peek(); self.add_decl(scope,tok.val,tok,'attr',None,False,False)
                self.i+=1
            self.i=save
        while self.peek() is not None and self.peek().val!='}':
            if is_kw(self.peek(),'inherit'):
                self.pop()
                if self.peek() and self.peek().val=='(':
                    self.pop(); e.children.append(self.parse_expr(scope,{')','EOF'}))
                    if self.peek() and self.peek().val==')': self.pop()
                    # inherited names from source are not variable refs
                    while self.peek() is not None and self.peek().val!=';': self.pop()
                else:
                    while self.peek() is not None and self.peek().val!=';':
                        if is_ident(self.peek()):
                            tok=self.pop(); e.refs.append(Ref(tok.val,tok,scope))
                        else: self.pop()
                if self.peek() and self.peek().val==';': self.pop()
                continue
            # Parse attr path until '='. Ignore literal attr names; parse parenthesized/dynamic path parts.
            while self.peek() is not None and self.peek().val not in {'=',';','}'}:
                if self.peek().val=='(':
                    self.pop(); e.children.append(self.parse_expr(scope,{')','EOF'}))
                    if self.peek() and self.peek().val==')': self.pop()
                else:
                    self.pop()
            if self.peek() and self.peek().val=='=':
                self.pop()
                valexpr=self.parse_expr(scope, {';','EOF'})
                e.children.append(valexpr)
            if self.peek() and self.peek().val==';': self.pop()
        if self.peek() and self.peek().val=='}': self.pop()
        if attr_scope:
            attr_scope.body=e
            # attr declarations are non-reporting; body active in this scope.
            wrapper=Expr(children=[e]); wrapper.lets.append(attr_scope)
            return wrapper
        return e

    def binding_remove_span(self, name_start):
        # Remove from beginning of line indentation if only whitespace before the binding; otherwise from name.
        s=name_start
        line_start=self.text.rfind('\n',0,name_start)+1
        if self.text[line_start:name_start].strip()=='' and line_start<name_start:
            s=line_start
        # find following semicolon and one optional following space/newline
        semi=self.text.find(';', name_start)
        if semi<0: return (name_start,name_start)
        e=semi+1
        if e < len(self.text) and self.text[e]=='\n': e+=1
        elif e < len(self.text) and self.text[e]==' ': e+=1
        return (s,e)

def resolve(scope, name):
    s=scope
    while s is not None:
        if name in s.byname and s.byname[name]:
            return s.byname[name][-1]
        s=s.parent
    return None

class Analyzer:
    def __init__(self, opts):
        self.opts=opts
        self.results=[]
        self.processing=set()

    def analyze(self, pr):
        if pr.errors:
            self.results.extend(pr.errors); return self.results
        self.activate_expr(pr.root, pr.root_scope)
        # Analyze nested scopes inside all expressions, even dead declarations, for their own diagnostics.
        self.activate_nested_for_reports(pr.root)
        for d in pr.decls:
            self.add_result_for_decl(d)
        self.results.sort(key=lambda r: (r.get('line',10**9), r.get('column',10**9), r.get('message','')))
        return self.results

    def activate_nested_for_reports(self, expr):
        # All child expressions/scopes have already been traversed when active in most cases; this pass ensures
        # lambda bodies and inner lets contained in dead values are still checked internally without propagating refs.
        for ch in expr.children:
            self.activate_nested_for_reports(ch)
        for sc in expr.lets:
            if isinstance(sc, Scope):
                # analyze its body in its own scope, then recurse into all decl values for internal reports
                if sc.body: self.activate_expr(sc.body, sc)
                for d in sc.decls:
                    if d.expr: self.activate_nested_for_reports(d.expr)
            else:
                self.activate_nested_for_reports(sc)

    def activate_expr(self, expr, default_scope):
        if expr is None: return
        for r in expr.refs:
            d=resolve(r.scope, r.name)
            if d:
                self.mark_used(d)
        for ch in expr.children:
            self.activate_expr(ch, default_scope)
        for sc in expr.lets:
            if isinstance(sc, Scope) and sc.kind in ('let','recattr'):
                if sc.body: self.activate_expr(sc.body, sc)

    def mark_used(self, d):
        if not d.used:
            d.used=True
            if d.expr and id(d) not in self.processing:
                self.processing.add(id(d))
                self.activate_expr(d.expr, d.scope)
                self.processing.discard(id(d))

    def add_result_for_decl(self, d):
        if d.kind=='attr': return
        name=d.name
        no_us = self.opts.no_underscore and name.startswith('_')
        if d.kind=='lambda_arg':
            if name.startswith('_'): return
            if self.opts.no_lambda_arg: return
            if no_us: return
            if (not d.used) and d.reportable:
                self.results.append(self.obj(d, f"Unused lambda argument: {name}"))
            return
        if d.kind=='lambda_pattern':
            if d.pattern_field and self.opts.no_lambda_pattern_names: return
            if no_us: return
            if d.used and self.opts.warn_used_underscore and name.startswith('_') and d.reportable:
                self.results.append(self.obj(d, f"Used lambda pattern: {name}"))
            elif (not d.used) and d.reportable:
                self.results.append(self.obj(d, f"Unused lambda pattern: {name}"))
            return
        if d.kind=='let':
            if no_us: return
            if d.used and self.opts.warn_used_underscore and name.startswith('_') and d.reportable:
                self.results.append(self.obj(d, f"Used let binding: {name}"))
            elif (not d.used) and d.reportable:
                self.results.append(self.obj(d, f"Unused let binding: {name}"))
            return

    def obj(self,d,msg):
        return {'column':d.tok.col,'endColumn':d.tok.col+len(d.name),'line':d.tok.line,'message':msg, '_decl':d}

@dataclass
class Opts:
    no_lambda_arg: bool=False
    no_lambda_pattern_names: bool=False
    no_underscore: bool=False
    warn_used_underscore: bool=False
    quiet: bool=False
    edit: bool=False
    hidden: bool=False
    fail: bool=False
    output_format: str='human-readable'
    excludes: list=field(default_factory=list)
    paths: list=field(default_factory=list)

HELP = """Find dead code in .nix files

Usage: {prog} [OPTIONS] [FILE_PATHS]...

Arguments:
  [FILE_PATHS]...  .nix files, or directories with .nix files inside [default: .]

Options:
  -l, --no-lambda-arg                  Don't check lambda parameter arguments
  -L, --no-lambda-pattern-names        Don't check lambda attrset pattern names (don't break nixpkgs callPackage)
  -_, --no-underscore                  Don't check any bindings that start with a _
                                       (Lambda arguments starting with _ are not checked anyway.)
  -W, --warn-used-underscore           Warn if bindings are referenced that start with '_'
  -q, --quiet                          Don't print dead code report
  -e, --edit                           Remove unused code and write to source file
  -h, --hidden                         Recurse into hidden subdirectories and process hidden .*.nix files
      --help                           
  -f, --fail                           Exit with 1 if unused code has been found
  -o, --output-format <OUTPUT_FORMAT>  Output format to use [default: human-readable] [possible values: human-readable, json]
      --exclude <EXCLUDES>...          Files to exclude from analysis
  -V, --version                        Print version
"""

def parse_args(argv):
    opts=Opts(); paths=[]; i=0; after_dd=False
    while i<len(argv):
        a=argv[i]
        if after_dd:
            paths.append(a); i+=1; continue
        if a=='--': after_dd=True; i+=1; continue
        if a in ('--help',): print(HELP.format(prog=os.path.basename(sys.argv[0])), end=''); sys.exit(0)
        if a in ('-V','--version'): print(VERSION); sys.exit(0)
        if a in ('-l','--no-lambda-arg'): opts.no_lambda_arg=True; i+=1; continue
        if a in ('-L','--no-lambda-pattern-names'): opts.no_lambda_pattern_names=True; i+=1; continue
        if a in ('-_','--no-underscore'): opts.no_underscore=True; i+=1; continue
        if a in ('-W','--warn-used-underscore'): opts.warn_used_underscore=True; i+=1; continue
        if a in ('-q','--quiet'): opts.quiet=True; i+=1; continue
        if a in ('-e','--edit'): opts.edit=True; i+=1; continue
        if a in ('-h','--hidden'): opts.hidden=True; i+=1; continue
        if a in ('-f','--fail'): opts.fail=True; i+=1; continue
        if a in ('-o','--output-format'):
            if i+1>=len(argv):
                sys.stderr.write("error: a value is required for '--output-format <OUTPUT_FORMAT>'\n"); sys.exit(2)
            opts.output_format=argv[i+1]; i+=2; continue
        if a.startswith('--output-format='):
            opts.output_format=a.split('=',1)[1]; i+=1; continue
        if a=='--exclude':
            i+=1
            while i<len(argv) and argv[i] != '--' and not argv[i].startswith('-'):
                opts.excludes.append(argv[i]); i+=1
            continue
        if a.startswith('--exclude='):
            opts.excludes.append(a.split('=',1)[1]); i+=1; continue
        if a.startswith('-') and a not in ('-',):
            sys.stderr.write(f"error: unexpected argument '{a}' found\n\nFor more information, try '--help'.\n")
            sys.exit(2)
        paths.append(a); i+=1
    if opts.output_format not in ('human-readable','json'):
        sys.stderr.write(f"error: invalid value '{opts.output_format}' for '--output-format <OUTPUT_FORMAT>'\n  [possible values: human-readable, json]\n\nFor more information, try '--help'.\n")
        sys.exit(2)
    opts.paths=paths or ['.']
    return opts

def is_hidden_path(path, root=None):
    base=os.path.basename(path)
    return base.startswith('.')

def collect_files(paths, opts):
    excl=set(os.path.abspath(x) for x in opts.excludes) | set(opts.excludes)
    out=[]
    for p in paths:
        if os.path.abspath(p) in excl or p in excl: continue
        if os.path.isdir(p):
            for dirpath, dirnames, filenames in os.walk(p):
                if not opts.hidden:
                    dirnames[:] = [d for d in dirnames if not d.startswith('.')]
                    filenames = [f for f in filenames if not f.startswith('.')]
                for f in filenames:
                    full=os.path.join(dirpath,f)
                    if not f.endswith('.nix'): continue
                    if os.path.abspath(full) in excl or full in excl: continue
                    out.append(full)
        else:
            out.append(p)
    return out

def strip_internal(results):
    clean=[]
    for r in results:
        d={k:v for k,v in r.items() if not k.startswith('_')}
        clean.append(d)
    return clean

def format_json(file, results):
    return json.dumps({'file':file,'results':strip_internal(results)}, separators=(',',':'))

def color(s, code, use):
    return f"\033[{code}m{s}\033[0m" if use else s

def human_report(file, text, results, use_color=True):
    if not results: return ''
    lines=text.splitlines() or ['']
    first=next((r for r in results if 'line' in r), None)
    loc=f"{file}:{first['line']}:{first['column']}" if first else file
    out=[f"{color('Warning:', '33', use_color)} Unused declarations were found."]
    out.append(f"    ╭─[{loc}]")
    byline={}
    for r in results:
        if 'line' in r: byline.setdefault(r['line'],[]).append(r)
        else: out.append(f"    · {r.get('message','')}")
    width=max(1,len(str(max(byline.keys()) if byline else 1)))
    for ln in sorted(byline):
        line_txt=lines[ln-1] if 1<=ln<=len(lines) else ''
        out.append(f" {str(ln).rjust(width)} │{line_txt}")
        for r in sorted(byline[ln], key=lambda x:x['column']):
            col=r['column']; length=max(1,r.get('endColumn',col+1)-col)
            marker=' '*(col-1)+'╰'+'─'*(max(0,length-2))
            if length>1: marker+='─'
            out.append(f" {' '*width} │{marker} {r['message']}")
    return '\n'.join(out)+'\n'

def apply_edits(text, decls, results):
    # Use result messages to select unused declarations only. Let bindings are removed; lambda args/patterns renamed or removed.
    unused=set()
    for r in results:
        msg=r.get('message','')
        if msg.startswith('Unused '):
            d=r.get('_decl')
            if d: unused.add(id(d))
    edits=[]
    # lambda simple args: prefix underscore
    for d in decls:
        if id(d) not in unused: continue
        if d.kind=='lambda_arg' and not d.name.startswith('_'):
            edits.append((d.tok.start,d.tok.start,'_'))
        elif d.kind=='let' and d.remove_span:
            edits.append((d.remove_span[0], d.remove_span[1], ''))
    # Pattern removal: repeatedly regex common forms around unused names. This is deliberately conservative.
    new=text
    for s,e,rep in sorted(edits, reverse=True):
        new=new[:s]+rep+new[e:]
    # Remove unused pattern fields by textual heuristics on the edited text.
    pat_names=[d.name for d in decls if id(d) in unused and d.kind=='lambda_pattern' and d.pattern_field]
    alias_names=[d.name for d in decls if id(d) in unused and d.kind=='lambda_pattern' and not d.pattern_field]
    for name in sorted(pat_names, key=len, reverse=True):
        # Remove `name ? default, ` or `name, `; if last before .../}, remove preceding comma.
        new=re.sub(r'\s*\b'+re.escape(name)+r'\b\s*\?\s*[^,}]+,', '', new)
        new=re.sub(r'\s*\b'+re.escape(name)+r'\b\s*,', '', new)
        new=re.sub(r',\s*\b'+re.escape(name)+r'\b\s*\?\s*[^,}]+', '', new)
        new=re.sub(r',\s*\b'+re.escape(name)+r'\b\s*', '', new)
    for name in sorted(alias_names, key=len, reverse=True):
        new=re.sub(r'\b'+re.escape(name)+r'\b@(?=\{)', '', new)
        new=re.sub(r'@\b'+re.escape(name)+r'\b', '', new)
    # Clean spacing inside patterns similar to formatter in common cases.
    new=re.sub(r'\{\s*,', '{', new)
    new=re.sub(r',\s*,', ',', new)
    new=re.sub(r'\{\s+', '{ ', new)
    new=re.sub(r'\s+\}', ' }', new)
    return new

def process_file(path, opts):
    try:
        with open(path,'r',encoding='utf-8') as f: text=f.read()
    except OSError as e:
        return [{'message':str(e)}], None, []
    p=Parser(text); pr=p.parse(); an=Analyzer(opts); results=an.analyze(pr)
    if opts.edit and results:
        new=apply_edits(text, pr.decls, results)
        if new!=text:
            try:
                with open(path,'w',encoding='utf-8') as f: f.write(new)
            except OSError:
                pass
    return results, text, pr.decls

def main(argv):
    opts=parse_args(argv)
    files=collect_files(opts.paths, opts)
    any_results=False
    outputs=[]
    for f in files:
        results,text,decls=process_file(f, opts)
        if results: any_results=True
        if opts.quiet or not results: continue
        if opts.output_format=='json': outputs.append(format_json(f, results))
        else: outputs.append(human_report(f, text or '', results, use_color=('NO_COLOR' not in os.environ)).rstrip('\n'))
    if not opts.quiet and outputs:
        sys.stdout.write('\n'.join(outputs))
        sys.stdout.write('\n')
    return 1 if (opts.fail and any_results) else 0

if __name__=='__main__':
    sys.exit(main(sys.argv[1:]))
